.line-banner__icon{flex:0 0 68px;width:68px;height:68px;display:grid;place-items:center;background:#ffffff21;border-radius:20px}.line-banner button{cursor:pointer}.line-dialog{width:min(430px,calc(100vw - 28px));padding:10px 18px 18px;color:var(--ink);background:var(--paper);border-radius:26px}.line-dialog__mark{width:76px;height:76px;display:grid;place-items:center;margin:18px auto 0;color:white;background:var(--sage);border-radius:24px}.line-dialog__copy{position:relative;text-align:center}.line-dialog__copy>button{position:absolute;top:-86px;right:-8px;width:44px;height:44px;display:grid;place-items:center;color:var(--chestnut);background:transparent;border:0;border-radius:50%;cursor:pointer}.line-dialog__copy small{color:var(--persimmon);font-weight:700}.line-dialog__copy h2{margin:10px 0 20px;font-size:1.75rem}.line-dialog__copy p{margin:0;color:var(--chestnut)}.line-dialog__copy strong{display:block;margin:5px 0 20px;font-size:1.35rem}.line-dialog__copy a{min-height:50px;display:inline-flex;align-items:center;gap:8px;padding:0 20px;color:white;background:var(--persimmon);border-radius:14px;font-weight:700;text-decoration:none}
@media(max-width:900px){.journey ol{grid-template-columns:repeat(2,minmax(0,1fr))}.journey-card:nth-child(even){margin-top:0}.caregiver-row{grid-auto-columns:minmax(340px,80vw)}}
@media(max-width:599px){.journey ol{grid-template-columns:1fr}.journey-card{min-height:300px}.caregiver-card{grid-template-columns:120px 1fr}.photo{min-height:230px}.line-dialog__copy h2{font-size:1.45rem}}
</style>
